def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def db_physical_state(db: Path) -> str:
    h = hashlib.sha256()
    for suffix in ("", "-wal"):
        p = Path(str(db) + suffix)
        h.update(suffix.encode("utf-8"))
        if not p.exists():
            h.update(b"MISSING")
            continue
        h.update(str(p.stat().st_size).encode("ascii"))
        h.update(sha256_file(p).encode("ascii"))
    return h.hexdigest()


def fail(message: str) -> None:
    print("\n" + "=" * 96)
    print("DỪNG AN TOÀN")
    print(message)
    print("Bộ cài V4.1 không thực hiện sáp nhập và không chủ động ghi phocap.db.")
    print("=" * 96)
    raise SystemExit(1)


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + ".v41_tmp")
    temp.write_bytes(data)
    os.replace(temp, path)


def main() -> None:
    root = Path(__file__).resolve().parent
    db = root / "data" / "phocap.db"
    print("=" * 96)
    print("BÀI SÁP NHẬP V4.1 - KHÓA KIỂM TRA TRƯỚC COMMIT")
    print(f"Dự án: {root}")
    print("Bộ cài chỉ nâng cổng an toàn V4 -> V4.1; KHÔNG chạy phương án sáp nhập.")
    print("=" * 96)

    if not (root / "app").is_dir() or not db.exists():
        fail(r"Hãy chép bộ cài vào đúng thư mục gốc C:\PhoCap rồi chạy lại.")

    for rel, expected in DEPENDENCY_HASHES.items():
        path = root / rel
        if not path.exists():
            fail(f"Thiếu tệp nền bắt buộc: {rel}")
        got = sha256_file(path)
        if got != expected:
            fail(
                f"Tệp nền {rel} khác phiên bản V4 đã kiểm thử.\n"
                f"SHA hiện tại: {got}\nSHA cần có: {expected}"
            )

    for rel, expected_v41 in EXPECTED_V41.items():
        path = root / rel
        if not path.exists():
            fail(f"Thiếu tệp V4 bắt buộc: {rel}")
        got = sha256_file(path)
        allowed = {EXPECTED_V4[rel], expected_v41}
        if got not in allowed:
            fail(
                f"Tệp {rel} đã bị thay đổi ngoài Bài V4/V4.1 nên bộ cài không tự ghi đè.\n"
                f"SHA hiện tại: {got}"
            )

    db_before = sha256_file(db)
    db_state_before = db_physical_state(db)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / "backups" / f"backup_truoc_bai_sap_nhap_v4_1_{stamp}"
    backup_dir.mkdir(parents=True, exist_ok=False)

    for rel in EXPECTED_V41:
        src = root / rel
        dst = backup_dir / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)

    try:
        for rel, encoded in EMBEDDED_FILES.items():
            atomic_write(root / rel, base64.b64decode(encoded))

        for rel, expected in EXPECTED_V41.items():
            got = sha256_file(root / rel)
            if got != expected:
                raise RuntimeError(f"SHA sau cài không đúng ở {rel}: {got}")

        py_compile.compile(str(root / "app" / "routers" / "school_merger.py"), doraise=True)
        py_compile.compile(str(root / "app" / "services" / "school_merger_preview_service.py"), doraise=True)
        py_compile.compile(str(root / "app" / "services" / "school_merger_execution_service.py"), doraise=True)

        sys.path.insert(0, str(root))
        importlib.invalidate_caches()
        from app.services.school_merger_official_registry import list_official_registry_plans
        from app.services.school_merger_preview_service import build_official_plan_impact_preview
        from app.services.school_merger_execution_service import (
            OFFICIAL_CONFIRM_PHRASE,
            execute_official_plan,
        )

        if OFFICIAL_CONFIRM_PHRASE != "SAP NHAP":
            raise RuntimeError("Câu xác nhận không đúng thiết kế: SAP NHAP")
        sig = inspect.signature(execute_official_plan)
        if "expected_impact_state_fingerprint" not in sig.parameters:
            raise RuntimeError("Backend chưa nhận dấu vân tay dữ liệu tác động V4.1.")
        if "expected_fingerprint" in sig.parameters:
            raise RuntimeError("Backend vẫn còn dùng tham số fingerprint V4 cũ ở endpoint chính thức.")

        cua_lo = [
            p for p in list_official_registry_plans(level_code="TH")
            if p.get("commune_excel") == "Cửa Lò"
        ]
        if len(cua_lo) != 4:
            raise RuntimeError(f"Cửa Lò - Tiểu học phải có 4 nhóm, hiện có {len(cua_lo)}.")
        mapped = [p for p in cua_lo if str(p.get("action_type") or "").upper() == "MAPPED"]
        if len(mapped) != 3:
            raise RuntimeError(f"Cửa Lò - Tiểu học phải có 3 nhóm nguồn→đích, hiện có {len(mapped)}.")

        preview_lines = []
        nghi_hoa_ok = False
        for plan in mapped:
            p1 = build_official_plan_impact_preview(str(plan["id"]))
            p2 = build_official_plan_impact_preview(str(plan["id"]))
            if p1.get("blockers"):
                raise RuntimeError(
                    f"Phương án {plan['id']} bị chặn: " + " | ".join(p1.get("blockers") or [])
                )
            if not p1.get("simulation_ok") or not p1.get("safe_for_future_execution"):
                raise RuntimeError(f"Phương án {plan['id']} chưa vượt qua mô phỏng.")
            if not p1.get("v41_state_check_ok") or not p1.get("impact_state_fingerprint"):
                raise RuntimeError(f"Phương án {plan['id']} chưa có cổng trạng thái V4.1.")
            if p1.get("impact_state_fingerprint") != p2.get("impact_state_fingerprint"):
                raise RuntimeError(f"Fingerprint V4.1 không ổn định khi DB không đổi: {plan['id']}")
            src_names = ", ".join(str(x.get("name") or x.get("excel_name") or "") for x in p1.get("source_schools") or [])
            dst_name = str((p1.get("target_school") or {}).get("name") or "")
            summary = p1.get("summary") or {}
            state = p1.get("impact_state_summary") or {}
            preview_lines.append(
                f" - {src_names} -> {dst_name}: V4.1 ĐẠT; "
                f"CURRENT/FUTURE={summary.get('direct_move_rows', 0)}; "
                f"PAST giữ={summary.get('historical_preserve_rows', 0)}; "
                f"rollover={summary.get('staff_rollover_candidates', 0)}; "
                f"khóa trạng thái={state.get('tables_or_scopes', 0)} phạm vi/{state.get('rows_hashed', 0)} dòng"
            )
            if "Nghi Hoà" in src_names and "Nghi Hải" in dst_name:
                if summary.get("direct_move_rows") != 10 or summary.get("staff_rollover_candidates") != 48:
                    raise RuntimeError("Nghi Hoà -> Nghi Hải không còn đúng bộ đếm kiểm thử V3/V4.")
                nghi_hoa_ok = True
        if not nghi_hoa_ok:
            raise RuntimeError("Không tìm thấy phương án kiểm chứng Nghi Hoà -> Nghi Hải.")

        router_text = (root / "app" / "routers" / "school_merger.py").read_text(encoding="utf-8")
        if 'impact_state_fingerprint: str = Form(default="")' not in router_text:
            raise RuntimeError("Router chưa nhận impact_state_fingerprint V4.1.")
        if "expected_impact_state_fingerprint=str(impact_state_fingerprint or \"\")" not in router_text:
            raise RuntimeError("Router chưa truyền fingerprint V4.1 vào backend.")

        template_text = (root / "app" / "templates" / "data_tools" / "school_merger_preview.html").read_text(encoding="utf-8")
        if "KIỂM TRA V4.1 ĐẠT" not in template_text:
            raise RuntimeError("Giao diện chưa có trạng thái xanh V4.1.")
        if 'name="impact_state_fingerprint"' not in template_text:
            raise RuntimeError("Form chưa gửi impact_state_fingerprint V4.1.")

        from jinja2 import Environment, FileSystemLoader
        env = Environment(loader=FileSystemLoader(str(root / "app" / "templates")))
        env.get_template("data_tools/school_merger_preview.html")
        env.get_template("data_tools/school_merger_result.html")

        db_after = sha256_file(db)
        db_state_after = db_physical_state(db)
        if db_before != db_after or db_state_before != db_state_after:
            raise RuntimeError("phocap.db/WAL đã thay đổi trong quá trình cài/kiểm thử V4.1.")

    except Exception as exc:
        for rel in EXPECTED_V41:
            backup = backup_dir / rel
            dest = root / rel
            if backup.exists():
                dest.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(backup, dest)
        fail("Cài đặt/kiểm thử V4.1 thất bại và mã nguồn đã được hoàn tác: " + str(exc))

    report = [
        "BÀI SÁP NHẬP V4.1 - CÀI ĐẶT THÀNH CÔNG",
        f"Thời gian: {datetime.now().isoformat(timespec='seconds')}",
        f"Dự án: {root}",
        f"Backup mã nguồn trước V4.1: {backup_dir}",
        "",
        "CỔNG V4.1 ĐÃ KHÓA:",
        " - Xem trước tạo impact_state_fingerprint của đúng tập dữ liệu liên quan.",
        " - POST thực hiện BEGIN IMMEDIATE rồi tính lại fingerprint trước backup/apply.",
        " - Nếu fingerprint đổi: CHẶN GHI và yêu cầu XEM TRƯỚC TÁC ĐỘNG lại.",
        " - Hash vật lý toàn DB chỉ tham chiếu; không còn bị so sai với hash bản xem trước.",
        " - Thay đổi không liên quan ở đơn vị khác không làm vô hiệu fingerprint phương án.",
        "",
        "AN TOÀN BỘ CÀI:",
        " - phocap.db + WAL trước/sau cài: KHÔNG THAY ĐỔI.",
        " - Bộ cài KHÔNG thực hiện bất kỳ phương án sáp nhập nào.",
        " - Vẫn giữ SAP NHAP + backup + một transaction + integrity/FK trước COMMIT + chống chạy lặp.",
        "",
        "KIỂM TRA CỬA LÒ - TIỂU HỌC:",
        *preview_lines,
        "",
        "BƯỚC TIẾP THEO:",
        " 1) Khởi động lại Uvicorn.",
        " 2) Cửa Lò -> Tiểu học -> Nghi Hoà -> Nghi Hải -> XEM TRƯỚC TÁC ĐỘNG.",
        " 3) Phải thấy dòng xanh: KIỂM TRA V4.1 ĐẠT – BẢN XEM TRƯỚC VẪN CÒN HIỆU LỰC.",
        " 4) CHƯA bấm THỰC HIỆN SÁP NHẬP; chụp mục 6-7 gửi kiểm tra lần cuối.",
    ]
    report_path = root / f"bao_cao_cai_bai_sap_nhap_v4_1_{stamp}.txt"
    report_path.write_text("\n".join(report) + "\n", encoding="utf-8")
    print("\n" + "\n".join(report))


if __name__ == "__main__":
    main()
